          status: ViewRevisionOutcome.ASSEMBLE_LOCAL,
          manifest_revision_digest: boot.readViewRevision?.(ctx)?.manifest_revision_digest,
          surface_revision_digest: boot.readViewRevision?.(ctx)?.surface_revision_digest,
